# ---------------------------------------------------------------- 열 관리 화면 인셋
# 전체 화면 DialogFragment 인데 인셋 처리가 없어 앱바가 상태바에 깔립니다.
def remove_once(path, needle, label):
    full = os.path.join(ROOT, path)
    if not os.path.exists(full):
        print("skipped (file missing): " + label)
        return
    text = open(full, encoding="utf-8").read()
    if needle not in text:
        print("already applied: " + label)
        return
    open(full, "w", encoding="utf-8").write(text.replace(needle, "", 1))
    print("patched " + label)

