optional_patch('AnkiDroid/src/main/java/com/ichi2/anki/noteeditor/NoteEditorMultimediaController.kt',
               '        val existingName =\n            try {\n                ContentResolverUtil.getFileName(resolver, uri)\n            } catch (e: Exception) {\n                Timber.i(e, "the provider gave no filename, copying the content instead")\n                null\n            }\n        if (existingName != null) return uri to description',
               '        // 이름을 받아도 확장자가 없으면 소용이 없습니다. 아래 파이프라인은\n        // FileNameAndExtension.fromString 으로 이름을 쪼개는데, 점이 없으면 null 을\n        // 돌려주고 "Unable to determine valid filename" 예외가 납니다. 그 예외가\n        // 오류 보고서로 이어집니다. 여기서 같은 기준으로 미리 걸러냅니다.\n        val existingName =\n            try {\n                ContentResolverUtil\n                    .getFileName(resolver, uri)\n                    .takeIf { name -> name.lastIndexOf(DOT) >= 1 }\n            } catch (e: Exception) {\n                Timber.i(e, "the provider gave no filename, copying the content instead")\n                null\n            }\n        if (existingName != null) return uri to description\n        Timber.i("no usable filename for the pasted media, copying the content instead")',
               "require a usable extension")

# ---------------------------------------------------------------- 중복 삽입 정리
# 함수를 넣는 패치는 나중 패치가 그 함수 안을 고치면 표식이 사라져, 다음 실행 때
# 같은 함수를 또 넣습니다. 위에서 표식을 명시해 재발은 막았고, 여기서는 이미
# 들어간 중복본을 지웁니다. 뒤에 나오는 쪽을 지우므로, 그동안의 수정이 반영된
# 앞쪽 정의가 남습니다.
def remove_duplicate_member(path, header, label):
    full = os.path.join(ROOT, path)
    if not os.path.exists(full):
        return
    text = open(full, encoding="utf-8").read()
    removed = 0
    while text.count(header) > 1:
        start = text.rindex(header)
        doc = text.rfind("    /**", 0, start)
        if doc != -1:
            close = text.find("*/", doc)
            if close != -1 and close < start and text[close + 2:start].strip() == "":
                start = doc
        brace = text.index("{", text.rindex(header))
        depth = 0
        end = None
        for index in range(brace, len(text)):
            if text[index] == "{":
                depth += 1
            elif text[index] == "}":
                depth -= 1
                if depth == 0:
                    end = index + 1
                    break
        if end is None:
            break
        while end < len(text) and text[end] == "\n":
            end += 1
        text = text[:start] + text[end:]
        removed += 1
    if removed:
        open(full, "w", encoding="utf-8").write(text)
        print("removed %d duplicate definition(s): %s" % (removed, label))
    else:
        print("no duplicates: " + label)


remove_duplicate_member('AnkiDroid/src/main/java/com/ichi2/anki/noteeditor/NoteEditorMultimediaController.kt', "    private fun copyIfUnnamed(", "copyIfUnnamed")
